// Spec-driven paperwork. The case model describes an exhibit as blocks (typed
// paragraph, ruled table, handwriting, stamp, redaction, signature); this turns
// that description into a believable scan with the same paper, ink and damage
// vocabulary as the CASE NX-037 art library, so 1994 and 2024 paperwork sit
// together in the archive without looking generated by two different people.

import '../../scripts/evidence-gen/lib/fontenv.mjs'
import { hashSeed } from '../../scripts/evidence-gen/lib/rng.mjs'
import { esc, stamp } from '../../scripts/evidence-gen/lib/print.mjs'
import {
  FONTS, wrapMono, typeBlock, rule, fieldRow, handwriting, redaction, signature,
} from '../../scripts/evidence-gen/lib/docpaper.mjs'
import { paperGround, damageLayer, finish } from '../../scripts/evidence-gen/lib/paper.mjs'
import { paperGrain } from '../../scripts/evidence-gen/lib/damage.mjs'

const { MONO, SERIF, SANS } = FONTS

const TONES = {
  bond: '#dcd6c4',
  ledger: '#d3cfba',
  carbon: '#cdcbc4',
  vellum: '#d9d5c0',
  card: '#e2d9bf',
  thermal: '#e6e4da',
}
const INK = { blue: '#232a3a', black: '#1c1a17', red: '#7a2b26' }
const STAMP = { red: '#7a2b26', blue: '#2c4a6b', black: '#2a2620' }

function seedOf(artifact) {
  return (hashSeed(artifact.id) % 90000) + 1000
}

/* ────────────────────────────── tables ────────────────────────────── */

function table(block, x, y, width, seed) {
  const size = 11
  const charW = size * 0.6
  const total = (block.widths ?? block.cols.map(() => 1)).reduce((a, b) => a + b, 0)
  const widths = (block.widths ?? block.cols.map(() => 1)).map(w => (w / total) * width)
  const xs = widths.reduce((acc, w, i) => (acc.push((acc[i] ?? x) + w), acc), [x]).slice(0, -1)
  const parts = []
  // header
  parts.push(`<rect x="${x}" y="${y}" width="${width}" height="22" fill="rgba(60,54,42,0.12)"/>`)
  block.cols.forEach((col, i) => {
    parts.push(`<text x="${(xs[i] + 6).toFixed(1)}" y="${y + 15}" font-family="${SANS}" font-size="9" letter-spacing="1.1" fill="#4a4437">${esc(String(col).toUpperCase())}</text>`)
  })
  let cy = y + 22
  parts.push(rule(x, cy, x + width, { color: '#3c362c', width: 0.9 }))
  block.rows.forEach((row, r) => {
    const wrapped = row.map((cell, i) => wrapMono(String(cell), Math.max(6, Math.floor((widths[i] - 12) / charW))))
    const lines = Math.max(...wrapped.map(w => Math.max(1, w.length)))
    const h = lines * 14 + 10
    if (r % 2 === 1) parts.push(`<rect x="${x}" y="${cy}" width="${width}" height="${h}" fill="rgba(80,72,56,0.05)"/>`)
    wrapped.forEach((cellLines, i) => {
      cellLines.forEach((line, k) => {
        parts.push(`<text x="${(xs[i] + 6).toFixed(1)}" y="${cy + 15 + k * 14}" font-family="${MONO}" font-size="${size}" letter-spacing="0.3" fill="#241f19" opacity="0.92" xml:space="preserve">${esc(line)}</text>`)
      })
    })
    if ((block.hi ?? []).includes(r)) {
      parts.push(`<path d="M ${x - 10} ${cy + h / 2 - 4} l 6 4 l -6 4" fill="none" stroke="${INK.blue}" stroke-width="1.6" stroke-opacity="0.75" stroke-linecap="round"/>`)
    }
    cy += h
    parts.push(rule(x, cy, x + width, { color: '#6f6653', width: 0.5, opacity: 0.8 }))
  })
  xs.slice(1).forEach(cx => {
    parts.push(`<line x1="${cx.toFixed(1)}" y1="${y}" x2="${cx.toFixed(1)}" y2="${cy}" stroke="#6f6653" stroke-width="0.4" stroke-opacity="0.5"/>`)
  })
  parts.push(`<rect x="${x}" y="${y}" width="${width}" height="${cy - y}" fill="none" stroke="#3c362c" stroke-width="0.8" stroke-opacity="0.7"/>`)
  void seed
  return { svg: parts.join(''), height: cy - y }
}

/* ────────────────────────────── page flow ────────────────────────────── */

function flow(a, W, M, startY) {
  const r = a.render
  const seed = seedOf(a)
  const parts = []
  const tableSpans = []
  const stamps = []
  let y = startY
  const textWidth = W - M * 2
  const columns = Math.floor(textWidth / (12.5 * 0.6))

  if (r.fields?.length) {
    const colW = r.fields.length > 3 ? textWidth / 2 - 10 : textWidth
    r.fields.forEach(([label, value], i) => {
      const col = r.fields.length > 3 ? i % 2 : 0
      const row = r.fields.length > 3 ? Math.floor(i / 2) : i
      parts.push(fieldRow({ x: M + col * (colW + 20), y: y + row * 24, width: colW, label, value, seed: seed + i }))
    })
    const rows = r.fields.length > 3 ? Math.ceil(r.fields.length / 2) : r.fields.length
    y += rows * 24 + 8
    parts.push(rule(M, y, W - M, { color: '#8d8471', width: 0.6 }))
    y += 26
  }

  ;(r.blocks ?? []).forEach((block, bi) => {
    const s = seed + bi * 13
    switch (block.t) {
      case 'p': {
        const lines = wrapMono(block.text, columns)
        parts.push(typeBlock(lines, { x: M, y, size: 12.5, leading: 18, color: '#2a2620', jitter: 0.3, seed: s }))
        y += lines.length * 18 + 14
        break
      }
      case 'mono': {
        const lines = block.lines.flatMap(l => wrapMono(l, columns).concat(l === '' ? [''] : []))
        parts.push(typeBlock(lines, { x: M, y, size: 12, leading: 17, color: '#2a2620', jitter: 0.3, seed: s }))
        y += lines.length * 17 + 14
        break
      }
      case 'table': {
        const t = table(block, M, y, textWidth, s)
        parts.push(t.svg)
        tableSpans.push([y - 4, y + t.height + 4])
        y += t.height + 16
        break
      }
      case 'hand': {
        const size = block.size ?? 16
        const x = M + (block.dx ?? 0)
        const base = y + (block.dy ?? 0) + (block.dy < 0 ? 0 : 20)
        const rot = block.rot ?? -2
        const hw = handwriting(block.text, { x, y: base, size, color: INK[block.color] ?? INK.blue, seed: s })
        parts.push(`<g transform="rotate(${rot} ${x} ${base})">${hw.svg}</g>`)
        if (!(block.dy < 0)) y += 34
        break
      }
      case 'stamp': {
        stamps.push({ block, y: y + (block.dy ?? 0), s })
        break
      }
      case 'redact': {
        parts.push(redaction(M, y - 12, block.w ?? 200, 15, { seed: s, label: block.label }))
        y += 24
        break
      }
      case 'sig': {
        parts.push(rule(M, y + 30, M + 230, { color: '#4a4437', width: 0.7 }))
        parts.push(signature(M + 6, y + 24, { seed: s, width: 170, name: block.name }))
        y += 56
        break
      }
      case 'rule':
        parts.push(rule(M, y, W - M, { color: '#8d8471', width: 0.7 }))
        y += 14
        break
      case 'gap':
        y += block.h ?? 12
        break
      default:
        throw new Error(`${a.id}: unknown block type "${block.t}"`)
    }
  })
  // Stamps are struck last, and kept off the tables unless the exhibit wants the overlap.
  for (const { block, y: sy } of stamps) {
    const size = block.size ?? 16
    const h = size * 3.1
    let top = sy
    if (!block.overlap) {
      for (const [a0, a1] of tableSpans) {
        if (top < a1 && top + h > a0) top = a1 + 8
      }
    }
    const bottomLimit = y + 40
    if (top > bottomLimit) top = bottomLimit
    parts.push(stamp({ x: M + (block.dx ?? 300), y: top, text: block.text, sub: block.sub, rotation: block.rot ?? -7, size, color: STAMP[block.color] ?? STAMP.red }))
    if (top + h > y) y = top + h + 6
  }
  return { svg: parts.join(''), end: y }
}

function header({ x, y, width, institute, unit, form, control, revision }) {
  const parts = []
  parts.push(`<text x="${x}" y="${y}" font-family="${SERIF}" font-size="21" letter-spacing="1.6" fill="#2b2720">${esc(institute)}</text>`)
  parts.push(`<text x="${x}" y="${y + 15}" font-family="${SANS}" font-size="9.5" letter-spacing="3.4" fill="#5a5344">${esc(unit ?? '')}</text>`)
  parts.push(rule(x, y + 24, x + width, { color: '#3c362c', width: 1.4 }))
  parts.push(rule(x, y + 27, x + width, { color: '#3c362c', width: 0.5 }))
  parts.push(`<text x="${x}" y="${y + 46}" font-family="${SANS}" font-size="13" letter-spacing="2.4" fill="#2b2720">${esc(form ?? '')}</text>`)
  const tag = [control, revision].filter(Boolean).join(' · ')
  if (tag) parts.push(`<text x="${x + width}" y="${y + 46}" text-anchor="end" font-family="${MONO}" font-size="10" letter-spacing="1.2" fill="#5a5344">${esc(tag)}</text>`)
  parts.push(rule(x, y + 52, x + width, { color: '#8d8471', width: 0.6 }))
  return parts.join('')
}

function ledgerRules(W, H, from) {
  const lines = []
  for (let yy = from; yy < H - 70; yy += 26) {
    lines.push(`<line x1="40" y1="${yy}" x2="${W - 40}" y2="${yy}" stroke="#8a9a8c" stroke-width="0.6" stroke-opacity="0.35"/>`)
  }
  lines.push(`<line x1="100" y1="${from - 20}" x2="100" y2="${H - 70}" stroke="#a8636a" stroke-width="0.9" stroke-opacity="0.4"/>`)
  return lines.join('')
}

function docSvg(a) {
  const r = a.render
  const seed = seedOf(a)
  const small = r.form === 'note' || r.form === 'card'
  const W = small ? 700 : 850
  const M = small ? 40 : 56
  const tone = TONES[r.stock] ?? TONES.bond
  const head = r.head
  const headerParts = []
  let y
  if (head) {
    headerParts.push(header({
      x: M, y: 74, width: W - M * 2,
      institute: head.org, unit: head.unit, form: head.form ?? r.title, control: head.control ?? '', revision: head.revision ?? '',
    }))
    y = 176
  } else {
    headerParts.push(`<text x="${M}" y="76" font-family="${SERIF}" font-size="${small ? 17 : 20}" letter-spacing="1.4" fill="#2b2720">${esc(r.title ?? a.title)}</text>`)
    headerParts.push(rule(M, 90, W - M, { color: '#3c362c', width: 1.1 }))
    y = 126
  }
  const body = flow(a, W, M, y)
  const H = Math.max(small ? 380 : 700, body.end + 110)

  const damageKind = r.damage?.kind ?? (a.condition && a.condition !== 'NORMAL' ? a.condition : null)
  const damageSpec = damageKind
    ? { seed, condition: damageKind === 'STAINED' ? 'STAIN' : damageKind, damageKind: damageKind === 'STAINED' ? 'STAIN' : damageKind }
    : { seed, condition: 'NORMAL' }

  const out = []
  out.push(paperGround({ width: W, height: H, seed, tone, warmth: 0.8, stock: r.stock === 'carbon' ? 'carbon' : 'bond' }))
  if (r.stock === 'ledger') out.push(ledgerRules(W, H, y))
  out.push(`<g transform="rotate(${(((seed % 7) - 3) * 0.12).toFixed(2)} ${W / 2} ${H / 2})">`)
  out.push(headerParts.join(''))
  out.push(body.svg)
  if (r.foot) {
    out.push(rule(M, H - 56, W - M, { color: '#6f6653', width: 0.7 }))
    out.push(`<text x="${M}" y="${H - 40}" font-family="${SANS}" font-size="8" letter-spacing="1.3" fill="#5c5546">${esc(r.foot)}</text>`)
  }
  out.push(`</g>`)
  out.push(damageLayer({ width: W, height: H, spec: damageSpec }))
  out.push(paperGrain({ width: W, height: H, seed, strength: 1.05 }))
  return { svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${out.join('')}</svg>`, W, H }
}

/* ────────────────────────────── receipts ────────────────────────────── */

function receiptSvg(a) {
  const r = a.render
  const seed = seedOf(a)
  const W = 420
  const lines = []
  lines.push({ t: r.shop ?? 'SHOP', size: 17, bold: true, center: true })
  if (r.address) lines.push({ t: r.address, size: 10, center: true })
  lines.push({ t: '-'.repeat(34), size: 11, center: true })
  for (const [item, price] of r.lines ?? []) lines.push({ item, price })
  lines.push({ t: '-'.repeat(34), size: 11, center: true })
  if (r.total) lines.push({ item: 'TOTAL', price: r.total, bold: true })
  if (r.time) lines.push({ t: r.time, size: 11, center: true })
  if (r.footer) lines.push({ t: r.footer, size: 10, center: true })
  const H = 130 + lines.length * 24
  const body = []
  body.push(`<rect width="${W}" height="${H}" fill="${TONES.thermal}"/>`)
  body.push(`<rect width="${W}" height="${H}" fill="#fff" opacity="0.2"/>`)
  let y = 70
  lines.forEach((l, i) => {
    if (l.item !== undefined) {
      body.push(`<text x="40" y="${y}" font-family="${MONO}" font-size="12.5" font-weight="${l.bold ? 'bold' : 'normal'}" fill="#2b2926" opacity="0.82" xml:space="preserve">${esc(l.item)}</text>`)
      body.push(`<text x="${W - 40}" y="${y}" text-anchor="end" font-family="${MONO}" font-size="12.5" font-weight="${l.bold ? 'bold' : 'normal'}" fill="#2b2926" opacity="0.82">${esc(l.price)}</text>`)
    } else {
      body.push(`<text x="${l.center ? W / 2 : 40}" y="${y}" text-anchor="${l.center ? 'middle' : 'start'}" font-family="${MONO}" font-size="${l.size ?? 12}" font-weight="${l.bold ? 'bold' : 'normal'}" fill="#2b2926" opacity="0.8" xml:space="preserve">${esc(l.t)}</text>`)
    }
    y += 24
    void i
  })
  const fade = `<rect x="0" y="0" width="${W}" height="${H}" fill="url(#rfade${seed})"/>`
  body.push(`<defs><linearGradient id="rfade${seed}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#000" stop-opacity="0.02"/><stop offset="1" stop-color="#6b5a34" stop-opacity="0.12"/></linearGradient></defs>${fade}`)
  body.push(paperGrain({ width: W, height: H, seed, strength: 0.7 }))
  return { svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${body.join('')}</svg>`, W, H }
}

/* ────────────────────────────── terminal screens ────────────────────────────── */

const THEMES = {
  amber: { bg: '#16100a', fg: '#e8b25a', dim: '#a07830', glow: '#e8b25a' },
  green: { bg: '#0d1410', fg: '#8fe0a2', dim: '#4f8a60', glow: '#8fe0a2' },
  white: { bg: '#10131a', fg: '#d8dde8', dim: '#7a8296', glow: '#aebce0' },
}

function screenSvg(a) {
  const r = a.render
  const seed = seedOf(a)
  const theme = THEMES[r.theme] ?? THEMES.green
  const W = 880
  const lines = r.lines ?? []
  const H = 120 + lines.length * 22 + 50
  const body = []
  body.push(`<defs>
    <radialGradient id="crt${seed}" cx="50%" cy="48%" r="75%"><stop offset="60%" stop-color="#000" stop-opacity="0"/><stop offset="100%" stop-color="#000" stop-opacity="0.65"/></radialGradient>
    <pattern id="scan${seed}" width="4" height="4" patternUnits="userSpaceOnUse"><rect width="4" height="1.4" fill="#000" opacity="0.22"/></pattern>
    <filter id="glow${seed}" x="-5%" y="-5%" width="110%" height="110%"><feGaussianBlur stdDeviation="1.6"/></filter>
  </defs>`)
  body.push(`<rect width="${W}" height="${H}" fill="${theme.bg}"/>`)
  body.push(`<rect x="0" y="0" width="${W}" height="34" fill="${theme.fg}" opacity="0.1"/>`)
  body.push(`<text x="20" y="23" font-family="${MONO}" font-size="13" letter-spacing="2" fill="${theme.fg}">${esc((r.title ?? a.title).toUpperCase())}</text>`)
  const text = []
  lines.forEach((line, i) => {
    const hi = (r.hi ?? []).includes(i)
    const yy = 70 + i * 22
    if (hi) text.push(`<rect x="12" y="${yy - 16}" width="${W - 24}" height="21" fill="${theme.fg}" opacity="0.92"/>`)
    text.push(`<text x="24" y="${yy}" font-family="${MONO}" font-size="14" letter-spacing="0.4" fill="${hi ? theme.bg : theme.fg}" xml:space="preserve">${esc(line)}</text>`)
  })
  body.push(`<g filter="url(#glow${seed})" opacity="0.7">${text.join('')}</g>`)
  body.push(text.join(''))
  body.push(`<rect width="${W}" height="${H}" fill="url(#scan${seed})"/>`)
  body.push(`<rect width="${W}" height="${H}" fill="url(#crt${seed})"/>`)
  body.push(paperGrain({ width: W, height: H, seed, strength: 0.5 }))
  return { svg: `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${body.join('')}</svg>`, W, H }
}

/* ────────────────────────────── public ────────────────────────────── */

export async function renderDocument(a) {
  const form = a.render?.form
  let built
  if (form === 'receipt') built = receiptSvg(a)
  else if (form === 'screen') built = screenSvg(a)
  else if (form === 'doc' || form === 'note' || form === 'card') built = docSvg(a)
  else throw new Error(`${a.id}: no document renderer for form "${form}"`)
  return finish(built.svg, built.W, built.H, { quality: 88 })
}
